sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {

   var currentField = 'likelihood';

   if (isLoading || newValue === '') { 
	if(newValue === ''){
	//significa que se quiere cambiar a un valor vacio
		g_form.setValue(currentField,oldValue);

		g_form.showFieldMsg(currentField,'You must not set this field to \'-- None -- \' ','error');

		// Promises run asynchronously
		var promise= new Promise(function(resolve,reject){
			setTimeout(solution, 2000);
			function solution(){
				g_form.hideFieldMsg(currentField,true);
				resolve("resolved");
			}
			reject(new Error('Problem with timeout?...'));
		});

		try{
			Promise.race([promise]);
		}catch(error){
			// there was an error?
		}

		return;
	}
   }

   var ga_InhRisk = new GlideAjax('x_1834695_risk_a_0.update_inhRisk');
   ga_InhRisk.addParam('sysparm_name','updateInhRisk');
   ga_InhRisk.addParam('impact',g_form.getValue('impact'));
   ga_InhRisk.addParam('likelihood', g_form.getValue('likelihood'));
   ga_InhRisk.getXMLAnswer(getResponse);

	// Service Now opens another thread to manage synchronusly the rest of the code
	function getResponse(response){
		var int_risk = JSON.parse(response).int_risk; 

		ga_InhRisk = new GlideAjax('x_1834695_risk_a_0.update_inhRisk');
		ga_InhRisk.addParam('sysparm_name','getInhRiskString');
		ga_InhRisk.addParam('intInhRisk',int_risk);
		ga_InhRisk.getXMLAnswer(setInhRisk);

		function setInhRisk(response){
			g_form.setValue('inh_risk',JSON.parse(response).text_risk);
		}
	}
}
